ensure(PHP_SAPI==='cli','Solo consola.',403);$root=dirname(__DIR__);$private=$root.'/.private';if(!is_dir($private))mkdir($private,0700,true);$file=getenv('TF_CONFIG_FILE')?:$private.'/config.json';
